    // is an invalid host character there; `new URL` treats it as a path slash.
    test('HuntB_url_refuses_backslash_in_authority', () => {
        const input = 'http://example.com' + BACKSLASH + 'path';
        const result = validateTextValue(huntField('url'), input);
        if (result?.id !== 'post_attributes.text_value.invalid_url') {
            throw new Error(`input ${JSON.stringify(input)}: expected invalid_url, got ${JSON.stringify(result)}`);
        }
    });

    test('HuntB_refused_url_value_is_never_committed_on_blur', () => {
        const onChange = renderControl(huntField('url'));
        const input = screen.getByTestId('post-attribute-input-contact');
        const typed = 'http://example.com/a' + String.fromCharCode(9) + 'b';

        fireEvent.change(input, {target: {value: typed}});
        fireEvent.blur(input);

        if (onChange.mock.calls.length) {
            throw new Error(`input ${JSON.stringify(typed)} was committed: ${JSON.stringify(onChange.mock.calls)}`);
        }
    });

    // "Input stops at the server's length limit": a keystroke inserted at the
    // start of a value already at the limit must not silently drop the tail.
    test('HuntB_insert_at_limit_does_not_drop_existing_tail', () => {
        const stored = 'a'.repeat(63) + 'Z';
        renderControl(huntField(), huntValue(stored));
        const input = screen.getByTestId('post-attribute-input-contact') as HTMLInputElement;
        expect(input.value).toBe(stored);

        const attempted = 'X' + stored;
        fireEvent.change(input, {target: {value: attempted}});

        if (!input.value.endsWith('Z') || input.value.length > 64) {
            throw new Error(`stored ${JSON.stringify(stored)}, typed X at start -> input became ${JSON.stringify(input.value)}`);
        }
    });
});

        cases.push({hasStored: true, stored: 'hello', disabled: true, valueType: vt, ops: [{kind: 'type', text: 'bye'}, {kind: 'blur'}]});
    }
    return cases;
}

